  const viaLiteral = deepParseWithTS(path.join(dir, 'cjs2.cjs'), 'module.exports = { f: function (z) { return z } }\n')
  check('module.exports = { f: function () {} } 仍有符号', Array.isArray(viaLiteral) && viaLiteral.some((s) => s.name === 'f'))
