  const symB = scanSymbols('a_b.ts', 'a_b.ts', 'export function alpha() { return 1 }\n').map((s) => s.id)
  check('符号表那条路径同样单射', symA.length > 0 && symB.length > 0 && !symA.some((id) => symB.includes(id)))
